var count = int.Parse(Console.ReadLine() ?? "");
var price = decimal.Parse(Console.ReadLine() ?? "", System.Globalization.CultureInfo.InvariantCulture);
var active = bool.Parse(Console.ReadLine() ?? "");
var total = count * price;
Console.WriteLine($"count={count}; total={total.ToString("F2", System.Globalization.CultureInfo.InvariantCulture)}; active={active.ToString().ToLowerInvariant()}");
